package net.civeira.phylax.feature.template.snippetasset.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.template.snippetasset.domain.SnippetAsset;
import net.civeira.phylax.feature.template.snippetasset.domain.valueobject.ContentVO;

class ContentValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of content of snippet asset")
  void test_content_value_holder_assign_plain_value() {
    Object holder = new Object();
    ContentValueHolder<Object> value = new ContentValueHolder<>(holder);
    Assertions.assertSame(holder, value.content("file_1"), "Setters must return the holder");
    Assertions.assertTrue(value.getContentValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("file_1", value.getContent().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of content of snippet asset")
  void test_content_value_holder_assign_value_object() {
    Object holder = new Object();
    ContentValueHolder<Object> value = new ContentValueHolder<>(holder);
    ContentVO vo = ContentVO.from("file_1");
    Assertions.assertFalse(value.getContentValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.content(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getContentValue().orElseThrow());
    Assertions.assertSame(holder, value.content(Optional.empty()));
    Assertions.assertFalse(value.getContentValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.content(Optional.of(vo)));
    Assertions.assertSame(vo, value.getContentValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of content of snippet asset against the original")
  void test_content_value_holder_read() {
    Object holder = new Object();
    ContentValueHolder<Object> value = new ContentValueHolder<>(holder);
    ContentVO vo = ContentVO.from("file_1");
    ContentVO other = ContentVO.from("file_1");
    SnippetAsset original = Mockito.mock(SnippetAsset.class);
    Mockito.when(original.getContentValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readContent(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readContent(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.content(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readContent(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readContent(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of content of snippet asset")
  void test_content_value_holder_unset() {
    Object holder = new Object();
    ContentValueHolder<Object> value = new ContentValueHolder<>(holder);
    ContentVO vo = ContentVO.from("file_1");
    value.content(vo);
    Assertions.assertSame(holder, value.unsetContentIfMatches("content_other"));
    Assertions.assertTrue(value.getContentValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetContentIfMatches("content"));
    Assertions.assertFalse(value.getContentValue().isPresent(),
        "The field name must clear the value");
    value.content(vo);
    Assertions.assertSame(holder, value.unsetContent());
    Assertions.assertFalse(value.getContentValue().isPresent(), "Unset must clear the value");
  }
}
